{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://halcyonthreshold.org/schema/incident-0.1.json",
  "title": "Frontier AI Incident Record v0.1",
  "description": "Structured record for coding frontier AI safety incidents against the Halcyon Threshold v0.1 taxonomy. Draft, untested.",
  "type": "object",
  "required": [
    "record_id",
    "coder",
    "coded_date",
    "sources",
    "summary",
    "primary_category",
    "barriers",
    "severity",
    "severity_basis",
    "confidence",
    "provisional"
  ],
  "properties": {
    "record_id": {
      "type": "string",
      "description": "Stable local id, e.g. HT-0001."
    },
    "coder": {
      "type": "string",
      "description": "Coder initials. Two independent coders per record in the pilot."
    },
    "coded_date": { "type": "string", "format": "date" },
    "sources": {
      "type": "array",
      "minItems": 1,
      "description": "Primary sources only. Public incident databases, regulator filings, developer postmortems, credible reporting. No inference presented as source.",
      "items": {
        "type": "object",
        "required": ["url", "source_type"],
        "properties": {
          "url": { "type": "string" },
          "source_type": {
            "enum": ["developer_postmortem", "regulator_filing", "incident_database", "journalism", "academic", "court_record", "other"]
          },
          "retrieved": { "type": "string", "format": "date" }
        }
      }
    },
    "event_date": {
      "type": "string",
      "description": "Date or range of the event itself, if known. Empty if undetermined."
    },
    "summary": {
      "type": "string",
      "description": "Two to four sentences, strictly what the sources support. No speculation."
    },
    "primary_category": {
      "enum": ["A", "B", "C", "D", "E", "F", "G", "H"],
      "description": "A capability surprise, B safeguard failure, C oversight/control degradation, D agentic action harm, E model asset security, F assurance integrity failure, G misuse with downstream harm, H systemic/dependency."
    },
    "secondary_categories": {
      "type": "array",
      "items": { "enum": ["A", "B", "C", "D", "E", "F", "G", "H"] }
    },
    "barriers": {
      "type": "object",
      "required": ["enumerated", "remaining_count"],
      "description": "Barrier analysis per taxonomy section 4. The enumeration matters more than the count.",
      "properties": {
        "enumerated": {
          "type": "array",
          "description": "Each barrier considered, whether it held, and whether it is independent of the others.",
          "items": {
            "type": "object",
            "required": ["description", "held", "independent"],
            "properties": {
              "description": { "type": "string" },
              "held": { "type": "boolean" },
              "independent": { "type": "boolean" },
              "relied_on_luck": {
                "type": "boolean",
                "description": "True if the barrier depended on chance, an alert bystander, or an actor choosing to stop. Such barriers do not count toward remaining_count."
              }
            }
          }
        },
        "remaining_count": { "type": "integer", "minimum": 0 },
        "notes": { "type": "string" }
      }
    },
    "severity": {
      "enum": ["S0", "S1", "S2", "S3", "S4"]
    },
    "severity_basis": {
      "type": "array",
      "minItems": 1,
      "description": "Which specific criteria from the severity scale were met. Cite the clause, e.g. 'S2: category C regardless of harm'.",
      "items": { "type": "string" }
    },
    "realized_harm": {
      "type": "object",
      "description": "Recorded separately from severity on purpose. Severity reflects potential; this field reflects outcome.",
      "properties": {
        "occurred": { "type": "boolean" },
        "reversible": { "enum": ["yes", "partially", "no", "unknown"] },
        "description": { "type": "string" }
      }
    },
    "reportable_under_v01": {
      "type": "boolean",
      "description": "True if severity is S2 or above."
    },
    "confidence": {
      "enum": ["high", "medium", "low"],
      "description": "Coder confidence given source quality, not confidence in the taxonomy."
    },
    "provisional": {
      "type": "boolean",
      "description": "True where classification rests on the most severe plausible reading under uncertainty."
    },
    "scheme_failure": {
      "type": "string",
      "description": "THE MOST IMPORTANT FIELD. Where the taxonomy did not fit, forced an arbitrary choice, or required knowledge the sources do not contain. Negative results are the deliverable."
    },
    "adjudication": {
      "type": "object",
      "description": "Completed only after the two coders' records are compared.",
      "properties": {
        "disagreed_on": {
          "type": "array",
          "items": { "enum": ["primary_category", "severity", "barrier_count", "provisional_status"] }
        },
        "resolution": { "type": "string" },
        "taxonomy_change_implied": { "type": "string" }
      }
    }
  },
  "additionalProperties": false
}

